import { useEffect, useState } from "react";
import { api, clearSession, getSession, saveSession } from "./lib/api";
import { startupNetworkCheck, type NetworkProviderResponse } from "./lib/network";
import { ReDomMark, ShieldIcon, LockIcon, HomeIcon } from "./components/Icons";
import { COUNTRIES } from "./data/countries";
import { WebExperience } from "./WebExperience";

type User={id:string;firstName:string;lastName:string;username:string;profilePhoto?:string|null};
type Page="startup"|"login"|"find-account"|"reset-code"|"reset-password"|"device-verify"|"two-factor"|"register-welcome"|"register-identity"|"register-birthday"|"register-gender"|"register-phone"|"register-email"|"register-password"|"register-review"|"register-verify"|"customizing"|"home"|"policy"|"support-case"|"web-parity";
type RegFlow={reservationId:string;flowId:string;expiresAt:string;firstName?:string;lastName?:string;dateOfBirth?:string;gender?:string;pronouns?:string;phoneNumber?:string;phoneCountry?:string;email?:string;passwordStrength?:"weak"|"medium"|"strong";rememberLoginInfo?:boolean};
const REG_KEY="redom.web.registration";
const DEVICE_KEY="redom.web.device";
const readReg=():RegFlow|null=>{try{const x=sessionStorage.getItem(REG_KEY);return x?JSON.parse(x):null}catch{return null}};
const writeReg=(x:RegFlow)=>sessionStorage.setItem(REG_KEY,JSON.stringify(x));
const deviceId=()=>{let x=localStorage.getItem(DEVICE_KEY);if(!x){x=crypto.randomUUID?crypto.randomUUID():"web-"+Date.now();localStorage.setItem(DEVICE_KEY,x)}return x};
const routePage=():Page|null=>{const p=window.location.pathname;if(/^\/policy\/[^/]+$/.test(p))return "policy";if(/^\/support\/cases\/R\d{11}$/i.test(p))return "support-case";if(/^\/app(?:\/|$)/i.test(p))return "web-parity";return null};
const pagePath=(p:Page)=>({home:"/app/homeFeed",login:"/app/login","find-account":"/app/findAccount","reset-code":"/app/resetCode","reset-password":"/app/resetPassword","device-verify":"/app/deviceVerification","two-factor":"/app/loginTwoFactor","register-welcome":"/app/registrationWelcome","register-identity":"/app/registrationIdentity","register-birthday":"/app/registrationBirthday","register-gender":"/app/registrationGender","register-phone":"/app/registrationPhone","register-email":"/app/registrationEmail","register-password":"/app/registrationPassword","register-review":"/app/registrationReview","register-verify":"/app/registrationVerification",customizing:"/app/customizingExperience"} as Partial<Record<Page,string>>)[p];
const ageFrom=(v:string)=>{const d=new Date(v+"T00:00:00"),n=new Date();let a=n.getFullYear()-d.getFullYear();const m=n.getMonth()-d.getMonth();if(m<0||(m===0&&n.getDate()<d.getDate()))a--;return a};
const fmt=(s:number)=>Math.floor(s/60)+":"+String(s%60).padStart(2,"0");
function useTimer(until?:string){const[s,setS]=useState(until?Math.max(0,Math.ceil((new Date(until).getTime()-Date.now())/1000)):0);useEffect(()=>{if(!until)return;const f=()=>setS(Math.max(0,Math.ceil((new Date(until).getTime()-Date.now())/1000)));f();const t=setInterval(f,1000);return()=>clearInterval(t)},[until]);return s}
function Shell({children}:{children:any}){return <div className="auth-wrap"><div className="auth-card"><section className="auth-content">{children}<small className="auth-foot">ReDom Platforms, Inc.</small></section><aside className="auth-security-rail"><div className="auth-security-icon"><ShieldIcon/></div><span className="eyebrow">REDOM SECURITY</span><h2>Protected from the foundation up.</h2><p>Every registration, login, recovery and sensitive account action is processed through the ReDom Backend security boundary.</p><div className="auth-security-list"><div><b>Network security</b><span>Connection checked before account access.</span></div><div><b>Device verification</b><span>New browsers and devices can require verification.</span></div><div><b>Session validation</b><span>Authenticated sessions are refreshed and invalidated when required.</span></div><div><b>Protected actions</b><span>Payment and security operations remain behind authenticated server checks.</span></div></div><div className="auth-security-status"><i/> Secure Web session</div></aside></div></div>}
function Field({label,value,onChange,type="text",placeholder=""}:{label:string;value:string;onChange:(v:string)=>void;type?:string;placeholder?:string}){return <label className="field"><span>{label}</span><input type={type} value={value} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></label>}
function ErrorBox({text}:{text:string}){return text?<div className="alert">{text}</div>:null}
function Primary({children,disabled,onClick}:{children:any;disabled?:boolean;onClick?:()=>void}){return <button className="btn primary xl full" disabled={disabled} onClick={onClick}>{children}</button>}
function Progress({step}:{step:number}){return <div className="stepbar">{Array.from({length:6},(_,i)=><i key={i} className={i<=step?"done":""}/>)}</div>}

function Startup({done,setNetwork}:{done:()=>void;setNetwork:(x:NetworkProviderResponse)=>void}){const[p,setP]=useState<NetworkProviderResponse|null>(null),[busy,setBusy]=useState(true);const run=async()=>{setBusy(true);const r=await startupNetworkCheck(api);setP(r);setNetwork(r);setBusy(false)};useEffect(()=>{void run()},[]);const s=p?.security;const warning=s?.vpn?"VPN connection detected.":s?.datacenter?"Datacenter connection detected.":s?.proxy?"Proxy connection detected.":s?.tor?"Tor connection detected.":s?.bot?"Automated traffic detected.":s?.abuser||Number(s?.fraudScore||0)>=75?"High security risk detected.":null;return <div className="startup-screen"><div className="startup-art"><img src="/startup.svg" alt="ReDom startup"/><div className="startup-spinner"><i/></div></div><div className="startup-overlay"><div className="startup-card"><div className="startup-icon"><ShieldIcon/></div><span className="eyebrow">ReDom Network Security</span><h1>{busy?"Checking Your Network":p?.success?"Network check complete":"Network Check Required"}</h1><p>{busy?"ReDom is checking your current network before Login opens.":p?.success?(p.networkProvider?p.networkProvider+" connection detected.":"Your connection has been checked."):(p?.warning||"ReDom could not complete the network security check.")}</p>{warning?<div className="warning-box"><ShieldIcon/><span>{warning} Review your connection before continuing.</span></div>:null}{s?<div className="security-rows"><div><span>Your IP</span><b>{s.ip||"Unknown"}</b></div><div><span>Connection</span><b>{s.connection||"Unknown"}</b></div><div><span>Provider</span><b>{p?.networkProvider||"Unknown"}</b></div><div><span>Location</span><b>{[s.city,s.region,s.country].filter(Boolean).join(", ")||"Unknown"}</b></div><div><span>Security score</span><b>{Number(s.fraudScore||0).toFixed(2)}%</b></div></div>:null}{p?.termsUrl?<a className="terms-link" href={p.termsUrl} target="_blank" rel="noreferrer">View provider terms</a>:null}{busy?<Primary disabled>Checking network…</Primary>:p?.success&&s?<Primary onClick={done}>OK, Continue</Primary>:<Primary onClick={()=>void run()}>Retry Network Check</Primary>}</div></div></div>}
function Login({go,network,setUser}:{go:(p:Page)=>void;network:NetworkProviderResponse|null;setUser:(u:User|null)=>void}){
 const[id,setId]=useState(""),[pw,setPw]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false);
 const[pendingOpen,setPendingOpen]=useState(false),[pendingMethods,setPendingMethods]=useState<any[]>([]),[pendingChallengeId,setPendingChallengeId]=useState<string|null>(null),[pendingTarget,setPendingTarget]=useState(""),[pendingCode,setPendingCode]=useState(""),[pendingError,setPendingError]=useState(""),[pendingBusy,setPendingBusy]=useState(false),[pendingSuccess,setPendingSuccess]=useState(false);
 const validateIdentifier=(v:string)=>{const x=v.trim();if(!x)return"Enter your mobile number or email.";if(x.startsWith("+")&&!/^\+[1-9]\d{7,14}$/.test(x))return"Enter your mobile number with + and the country code.";if(/^\d+$/.test(x)&&(x.length<7||x.length>20))return"Enter a valid mobile number.";if(!/^\d+$/.test(x)&&!x.startsWith("+")&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x))return"Enter a valid mobile number or email address.";return null};
 const submit=async()=>{
  if(busy)return;setErr("");
  const idError=validateIdentifier(id);if(idError){setErr(idError);return}if(!pw){setErr("Enter your password.");return}
  let identifier=id.trim();if(/^0\d+$/.test(identifier)&&network?.security?.callingCode)identifier="+"+String(network.security.callingCode).replace(/\D/g,"")+identifier.slice(1);
  if(/^\d+$/.test(id.trim())&&id.trim().startsWith("0")&&!identifier.startsWith("+")){setErr("We could not determine your country code from the startup network check. Enter your number with + and the country code.");return}
  setBusy(true);
  try{
   const r=await api<any>("/auth/login",{method:"POST",body:JSON.stringify({identifier,password:pw,platform:"web",deviceId:deviceId(),deviceType:"browser",deviceName:navigator.userAgent,loginSource:"web",browser:navigator.userAgent,appVersion:"web",networkIp:network?.security?.ip||undefined})});
   if(r.requiresVerification&&r.verification){sessionStorage.setItem("redom.login.challenge",JSON.stringify(r.verification));go("device-verify");return}
   if(r.requiresTwoFactor&&r.twoFactorVerification){sessionStorage.setItem("redom.login.2fa",JSON.stringify(r.twoFactorVerification));go("two-factor");return}
   if(r.success&&r.user&&r.session){saveSession(r.session);setUser({...r.user});go("home");return}
   const message=r.message||"Sign in could not be completed.";if(/pending verification/i.test(message)){
    try{const p=await api<any>("/auth/pending-registration/options",{method:"POST",body:JSON.stringify({identifier,password:pw})});setPendingMethods(p.methods||[]);setPendingOpen(true);return}catch{}
   }setErr(message);
  }catch(e){
   const message=e instanceof Error?e.message:"Sign in failed.";
   if(/pending verification/i.test(message)){try{const p=await api<any>("/auth/pending-registration/options",{method:"POST",body:JSON.stringify({identifier,password:pw})});setPendingMethods(p.methods||[]);setPendingOpen(true);}catch{setErr(message)}}else setErr(message);
  }finally{setBusy(false)}
 };
 const sendPending=async(method:any)=>{setPendingBusy(true);setPendingError("");try{const r=await api<any>("/auth/pending-registration/send",{method:"POST",body:JSON.stringify({identifier:id.trim(),password:pw,channel:method.channel,deviceId:deviceId()})});setPendingChallengeId(r.challengeId);setPendingTarget(r.target);setPendingCode("");setPendingOpen(false);}catch(e){setPendingError(e instanceof Error?e.message:"Unable to send the verification code.");}finally{setPendingBusy(false)}};
 const invalidate=async()=>{if(!pendingChallengeId||pendingCode.length!==4)return;setPendingBusy(true);setPendingError("");try{const r=await api<any>("/auth/pending-registration/invalidate",{method:"POST",body:JSON.stringify({challengeId:pendingChallengeId,code:pendingCode,deviceId:deviceId()})});if(!r.success||!r.invalidated)throw new Error(r.message||"The pending registration could not be invalidated.");setPendingSuccess(true);}catch(e){setPendingError(e instanceof Error?e.message:"Invalid Code. Enter the 4-digit verification code.");}finally{setPendingBusy(false)}};
 return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Welcome back</h1><p>Sign in to your ReDom account.</p><div className="auth-form"><ErrorBox text={err}/><Field label="Email, phone or username" value={id} onChange={v=>{setId(v);setErr("")}}/><Field label="Password" value={pw} onChange={v=>{setPw(v);setErr("")}} type="password"/><Primary disabled={busy} onClick={()=>void submit()}>{busy?"Signing in…":"Sign in"}</Primary><button className="text-btn" onClick={()=>go("find-account")}>Forgot password?</button><div className="auth-divider">or</div><button className="btn secondary xl full" onClick={()=>go("register-welcome")}>Create new account</button></div>
 {pendingOpen?<div className="web-modal-backdrop"><div className="web-sheet pending-sheet"><div className="security-hero"><SvgAsset src={SecurityShieldSvg} className="auth-svg-icon" /></div><h2>Your account is pending verification</h2><p>This ReDom registration has not been verified yet. You can verify it now, or invalidate the pending registration and start again.</p><b>Send a 4-digit verification code to:</b>{pendingMethods.map((m:any)=><button className="choice" key={m.channel} onClick={()=>void sendPending(m)}>{m.channel==="email"?"Email":"Phone"} · {m.target}</button>)}<button className="text-btn" onClick={()=>setPendingOpen(false)}>Cancel</button></div></div>:null}
 {pendingChallengeId&&!pendingSuccess?<div className="web-modal-backdrop"><div className="web-sheet pending-sheet"><div className="security-hero"><SvgAsset src={SecurityShieldSvg} className="auth-svg-icon" /></div><h2>Verify your pending registration</h2><p>Enter the 4-digit code sent to {pendingTarget}.</p><Field label="4-digit verification code" value={pendingCode} onChange={v=>{setPendingCode(v.replace(/\D/g,"").slice(0,4));setPendingError("")}}/><ErrorBox text={pendingError}/><Primary disabled={pendingBusy||pendingCode.length!==4} onClick={()=>void invalidate()}>{pendingBusy?"Verifying…":"Verify Code"}</Primary><button className="text-btn" onClick={()=>{setPendingChallengeId(null);setPendingCode("")}}>Cancel</button></div></div>:null}
 {pendingSuccess?<div className="web-modal-backdrop"><div className="web-sheet pending-sheet"><div className="success-icon">✓</div><h2>Your Pending Registration Has Been Invalidated</h2><p>The unverified registration and associated data have been permanently deleted. The previous Registration Flow ID is no longer valid.</p><Primary onClick={()=>{setPendingSuccess(false);setPendingChallengeId(null);setPendingCode("");setId("");setPw("");go("register-welcome")}}>Create Account</Primary></div></div>:null}
 </Shell>
}

function FindAccount({go}:{go:(p:Page)=>void}){
 const[id,setId]=useState(""),[methods,setMethods]=useState<any[]>([]),[err,setErr]=useState(""),[busy,setBusy]=useState(false);
 const lookup=async()=>{setBusy(true);setErr("");try{const r=await api<any>("/auth/find-account",{method:"POST",body:JSON.stringify({identifier:id.trim()})});setMethods(r.methods||r.channels||[]);if(!(r.methods||r.channels||[]).length)setErr(r.message||"No recovery methods are available.")}catch(e){setErr(e instanceof Error?e.message:"Unable to find the account.")}finally{setBusy(false)}};
 const choose=async(m:any)=>{setBusy(true);try{const channel=m.channel||m.type;const r=await api<any>("/auth/password-reset/send",{method:"POST",body:JSON.stringify({identifier:id.trim(),channel,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",browser:navigator.userAgent,appVersion:"web"})});sessionStorage.setItem("redom.reset",JSON.stringify({challengeId:r.challengeId,identifier:id.trim(),maskedTarget:r.maskedTarget,expiresAt:r.expiresAt}));go("reset-code")}catch(e){setErr(e instanceof Error?e.message:"Unable to send the reset code.")}finally{setBusy(false)}};
 return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Find your account</h1><p>Enter the email, phone number, or username connected to ReDom.</p><div className="auth-form"><ErrorBox text={err}/><Field label="Email, phone or username" value={id} onChange={setId}/><Primary disabled={busy||!id.trim()} onClick={()=>void lookup()}>{busy?"Checking…":"Find account"}</Primary>{methods.length?<div className="recovery-methods"><b>Choose where to receive your code</b>{methods.map((m,i)=><button className="choice" key={i} onClick={()=>void choose(m)}>{m.label||m.maskedTarget||m.channel||m.type}</button>)}</div>:null}<button className="text-btn" onClick={()=>go("login")}>Back to login</button></div></Shell>
}

function ResetCode({go}:{go:(p:Page)=>void}){const d=JSON.parse(sessionStorage.getItem("redom.reset")||"null")||{},[code,setCode]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),sec=useTimer(d.expiresAt);const verify=async()=>{if(code.length!==5)return setErr("Enter the 5-digit verification code.");setBusy(true);setErr("");try{const r=await api<any>("/auth/password-reset/verify",{method:"POST",body:JSON.stringify({challengeId:d.challengeId,code,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",appVersion:"web",language:navigator.language})});if(!r.success||!r.resetToken)throw new Error(r.message||"Verification code is incorrect.");sessionStorage.setItem("redom.resetToken",r.resetToken);go("reset-password")}catch(e){setErr(e instanceof Error?e.message:"Verification failed.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Enter your code</h1><p>Code sent to <b>{d.maskedTarget||"your recovery method"}</b>.</p><div className="auth-form"><ErrorBox text={err}/><Field label="5-digit verification code" value={code} onChange={v=>setCode(v.replace(/\D/g,"").slice(0,5))}/><Primary disabled={busy||code.length!==5||sec<=0} onClick={()=>void verify()}>{busy?"Verifying…":"Verify code"}</Primary><small className="auth-note">{sec>0?"Code expires in "+fmt(sec):"Code expired"}</small><button className="text-btn" onClick={()=>go("login")}>Back to login</button></div></Shell>}
function ResetPassword({go}:{go:(p:Page)=>void}){const[a,setA]=useState(""),[b,setB]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false);const letters=/\p{L}/u.test(a),numbers=/\p{N}/u.test(a),common=/^(123456|1234567|12345678|password|password1|qwerty|qwerty123|abcdef|abcdefg|111111|000000|letmein)$/iu.test(a);let percent=Math.min(50,Math.max(0,Math.round((a.length-6)*8.34)))+(letters?25:0)+(numbers?25:0);if(!letters||!numbers)percent=Math.min(percent,49);if(common)percent=Math.min(percent,23);const save=async()=>{if(percent!==100||!letters||!numbers)return setErr("Create a 100% Strong password.");if(a!==b)return setErr("Passwords do not match.");setBusy(true);try{const r=await api<any>("/auth/password-reset/change",{method:"POST",body:JSON.stringify({resetToken:sessionStorage.getItem("redom.resetToken"),password:a,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",browser:navigator.userAgent,appVersion:"web",language:navigator.language})});if(!r.success)throw new Error(r.message||"Unable to change password.");sessionStorage.removeItem("redom.reset");sessionStorage.removeItem("redom.resetToken");go("login")}catch(e){setErr(e instanceof Error?e.message:"Unable to change password.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Create a new password</h1><p>Choose a strong password for your ReDom account.</p><div className="auth-form"><Field label="New password" value={a} onChange={setA} type="password"/><Field label="Confirm password" value={b} onChange={setB} type="password"/><div className="strength"><div><span>Password strength</span><b>{percent===100?"Strong":percent>=75?"Good":percent>=50?"Fair":percent>0?"Weak":"Too short"}</b><span>{percent}%</span></div><div className="strength-bar"><i style={{width:percent+"%"}}/></div></div><ErrorBox text={err}/><Primary disabled={busy||percent!==100||a!==b} onClick={()=>void save()}>{busy?"Saving…":"Save password"}</Primary></div></Shell>}
function RegHeader({step,flow}:{step:number;flow:RegFlow}){const sec=useTimer(flow.expiresAt);return <><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><div className="flow-meta"><span><SvgAsset src={LockedKeySvg} className="flow-lock-svg" />Flow ID: {flow.flowId}</span><span>{sec>0?fmt(sec):"Expired"}</span></div><Progress step={step}/></>}
function RegisterWelcome({go}:{go:(p:Page)=>void}){const[busy,setBusy]=useState(false),[err,setErr]=useState("");const start=async()=>{setBusy(true);setErr("");try{const r=await api<any>("/auth/register/flow",{method:"POST",body:JSON.stringify({deviceId:deviceId()})});writeReg({reservationId:r.reservationId,flowId:r.flowId,expiresAt:r.expiresAt});go("register-identity")}catch(e){setErr(e instanceof Error?e.message:"Unable to start registration.")}finally{setBusy(false)}};return <Shell><RegHeader step={0} flow={readReg()||{reservationId:"",flowId:"",expiresAt:new Date(Date.now()+600000).toISOString()}}/><h1>Join ReDom today</h1><p>Create your account through the protected ReDom registration flow.</p><ErrorBox text={err}/><Primary disabled={busy} onClick={()=>void start()}>{busy?"Preparing…":"Create account"}</Primary><button className="text-btn" onClick={()=>go("login")}>Back to login</button></Shell>}

function RegIdentity({flow,go,setFlow}:{flow:RegFlow;go:(p:Page)=>void;setFlow:(f:RegFlow)=>void}){
 const[a,setA]=useState(flow.firstName||""),[b,setB]=useState(flow.lastName||""),[err,setErr]=useState(""),[busy,setBusy]=useState(false);
 const sanitize=(v:string)=>v.normalize("NFC").replace(/[^\p{L}\s.,'-]/gu,"").replace(/\s+/g," ");
 const validate=(v:string,label:string)=>{const n=v.normalize("NFC").trim().replace(/\s+/g," ");if(n.length<3)return label+" must be at least 3 characters.";if(!/^[\p{L}][\p{L}\s.,'-]*$/u.test(n))return label+" contains unsupported characters.";if(/^[.,'-]|[.,'-]$/.test(n)||/[.,'-]{2,}/.test(n))return label+" contains invalid punctuation.";if(["test","testing","asdf","qwerty","admin","name","firstname","lastname","unknown","none","null"].includes(n.toLowerCase()))return "Enter your real "+label.toLowerCase()+".";return null};
 const next=async()=>{const e=validate(a,"First name")||validate(b,"Last name");if(e){setErr(e);return}setBusy(true);try{await api("/auth/register/flow/"+flow.reservationId+"/name",{method:"PATCH",body:JSON.stringify({flowId:flow.flowId,deviceId:deviceId(),firstName:sanitize(a).trim(),lastName:sanitize(b).trim()})});setFlow({...flow,firstName:sanitize(a).trim(),lastName:sanitize(b).trim()});go("register-birthday")}catch(e){setErr(e instanceof Error?e.message:"Unable to save your name.")}finally{setBusy(false)}};
 return <Shell><RegHeader step={1} flow={flow}/><h1>What's your name?</h1><p>Use the name you use in everyday life.</p><div className="auth-form"><ErrorBox text={err}/><div className="two"><Field label="First name" value={a} onChange={v=>{setA(sanitize(v));setErr("")}}/><Field label="Last name" value={b} onChange={v=>{setB(sanitize(v));setErr("")}}/></div><Primary disabled={busy} onClick={()=>void next()}>{busy?"Saving…":"Continue"}</Primary></div></Shell>
}

function RegBirthday({flow,go,setFlow}:{flow:RegFlow;go:(p:Page)=>void;setFlow:(f:RegFlow)=>void}){const[d,setD]=useState(flow.dateOfBirth||""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),[notice,setNotice]=useState<"teen"|"underage"|null>(null);const next=async()=>{if(!d)return setErr("Choose your date of birth.");setBusy(true);try{const r=await api<any>("/auth/register/flow/"+flow.reservationId+"/birthday",{method:"PATCH",body:JSON.stringify({flowId:flow.flowId,deviceId:deviceId(),dateOfBirth:d})});setFlow({...flow,dateOfBirth:d});if(r.ageBand==="underage"||ageFrom(d)<13){setNotice("underage");return}if(r.ageBand==="teen"||ageFrom(d)<17){setNotice("teen");return}go("register-gender")}catch(e){setErr(e instanceof Error?e.message:"Unable to save your birthday.")}finally{setBusy(false)}};return <Shell><RegHeader step={2} flow={flow}/><h1>What's your birthday?</h1><p>Choose the birthday you use in everyday life.</p><div className="auth-form"><ErrorBox text={err}/><Field label="Date of birth" value={d} onChange={setD} type="date"/><Primary disabled={busy} onClick={()=>void next()}>{busy?"Saving…":"Continue"}</Primary></div>{notice?<div className={notice==="underage"?"modal-inline danger":"modal-inline"}><ShieldIcon/><h3>{notice==="underage"?"We can't continue with this account.":"A safety reminder before you continue"}</h3><p>{notice==="underage"?"The birthday entered does not meet ReDom's minimum age requirements, so this registration flow cannot continue.":"Because you are 13–16, protect your password and private information, avoid sharing sensitive information with people you do not know, and tell a trusted adult if something online makes you uncomfortable."}</p><Primary onClick={()=>{if(notice==="underage"){sessionStorage.removeItem(REG_KEY);go("login")}else{setNotice(null);go("register-gender")}}}>{notice==="underage"?"OK":"I understand & continue"}</Primary></div>:null}</Shell>}

