 useEffect(()=>{let live=true;(async()=>{try{const ip=network?.security?.ip||"";const r=await api<any>("/auth/register/flow/"+flow.reservationId+"/phone-country?flowId="+encodeURIComponent(flow.flowId)+"&deviceId="+encodeURIComponent(deviceId())+"&deviceRegion="+encodeURIComponent(navigator.language.slice(-2).toUpperCase())+"&timeZone="+encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone)+"&ip="+encodeURIComponent(ip));if(live&&r.countryCode){const found=COUNTRIES.find((x:any)=>x.code===r.countryCode);if(found)setCountry(found)}}catch{}})();return()=>{live=false}},[flow.reservationId,flow.flowId,network?.security?.ip]);
