function RegReview({flow,go,network}:{flow:RegFlow;go:(p:Page)=>void;network:NetworkProviderResponse|null}){const[agreed,setAgreed]=useState(false),[err,setErr]=useState(""),[busy,setBusy]=useState(false),[memory,setMemory]=useState<any>(null);useEffect(()=>{api<any>("/auth/register/flow/"+flow.reservationId+"/memory?flowId="+encodeURIComponent(flow.flowId)+"&deviceId="+encodeURIComponent(deviceId())).then(r=>setMemory(r.memory)).catch(e=>setErr(e instanceof Error?e.message:"Unable to load registration details."))},[flow]);const submit=async()=>{if(!agreed)return setErr("Agree to the ReDom Terms and Privacy Policy to continue.");setBusy(true);setErr("");try{const contactType=flow.email?"email":"phone";const target=flow.email||flow.phoneNumber||"";const c=await api<any>("/auth/register/challenge",{method:"POST",body:JSON.stringify({contactType,target,deviceId:deviceId(),reservationId:flow.reservationId,flowId:flow.flowId})});await api("/auth/register/challenge/"+c.challengeId,{method:"PATCH",body:JSON.stringify({step:"review",data:{firstName:flow.firstName,lastName:flow.lastName,username:(String(flow.firstName||"")+String(flow.lastName||"")).toLowerCase().replace(/[^a-z0-9]/g,"")+"_"+Math.floor(1000+Math.random()*9000),email:flow.email,phoneNumber:flow.phoneNumber,dateOfBirth:flow.dateOfBirth,gender:flow.gender}})});const done=await api<any>("/auth/register/challenge/"+c.challengeId+"/complete",{method:"POST",body:JSON.stringify({submitted:flow.email?{email:flow.email}:{phoneNumber:flow.phoneNumber}})});sessionStorage.setItem("redom.registration.verification",JSON.stringify({verificationChallengeId:done.verification.challengeId,reservationId:flow.reservationId,flowId:done.flowId,channel:done.verification.channel,maskedTarget:done.verification.maskedTarget,expiresAt:done.verification.expiresAt}));go("register-verify")}catch(e){setErr(e instanceof Error?e.message:"Unable to start verification.")}finally{setBusy(false)}};return <Shell><RegHeader step={6} flow={flow}/><h1>Review and agree to ReDom Terms</h1><p>Review the account, privacy, security and community requirements before creating your account.</p><div className="review-list">{["Account controls","Personal information","Password safety","Network security","Community Guidelines"].map(x=><div className="review-item" key={x}><ShieldIcon/><div><b>{x}</b><p>ReDom uses this registration step to protect your account and keep the service safe.</p></div></div>)}</div>{memory?<div className="memory-card"><b>Registration details</b><span>{memory.identity?.firstName||flow.firstName} {memory.identity?.lastName||flow.lastName}</span><span>{memory.email?.address||flow.email||flow.phoneNumber}</span><span>{memory.birthday?.dateOfBirth||flow.dateOfBirth}</span></div>:null}<ErrorBox text={err}/><label className="check-line"><input type="checkbox" checked={agreed} onChange={e=>setAgreed(e.target.checked)}/> I understand and agree to the ReDom Terms and Privacy Policy.</label><Primary disabled={!agreed||busy} onClick={()=>void submit()}>{busy?"Preparing verification…":"I Understand, Sign Up"}</Primary></Shell>}

function RegVerify({go}:{go:(p:Page)=>void}){const d=JSON.parse(sessionStorage.getItem("redom.registration.verification")||"null")||{},[challenge,setChallenge]=useState(d),[code,setCode]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),[seconds,setSeconds]=useState(120),sec=useTimer(challenge.expiresAt);useEffect(()=>{const t=setInterval(()=>setSeconds(v=>Math.max(0,v-1)),1000);return()=>clearInterval(t)},[]);const verify=async()=>{if(code.length!==6||sec<=0)return;setBusy(true);setErr("");try{const r=await api<any>("/auth/register/verification/"+challenge.verificationChallengeId+"/verify",{method:"POST",body:JSON.stringify({verificationChallengeId:challenge.verificationChallengeId,code})});if(!r.success)throw new Error(r.message||"Verification failed.");go("customizing")}catch(e){const m=e instanceof Error?e.message:"Verification failed.";setErr(/expired/i.test(m)?"Verification code has expired.":/invalid|incorrect/i.test(m)?"Verification Code Is Incorrect.":m)}finally{setBusy(false)}};const resend=async()=>{if(seconds>0||busy)return;setBusy(true);setErr("");try{const r=await api<any>("/auth/register/verification/"+challenge.verificationChallengeId+"/resend",{method:"POST",body:JSON.stringify({verificationChallengeId:challenge.verificationChallengeId,reservationId:challenge.reservationId,flowId:challenge.flowId,deviceId:deviceId()})});const next={...challenge,...r,verificationChallengeId:r.verificationChallengeId,flowId:r.rawFlowId||r.flowId};setChallenge(next);sessionStorage.setItem("redom.registration.verification",JSON.stringify(next));setCode("");setSeconds(120)}catch(e){setErr(e instanceof Error?e.message:"Unable to resend the verification code.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><div className="flow-meta"><span>Flow ID: {challenge.flowId||""}</span><span>{sec>0?fmt(sec):"Expired"}</span></div><h1>Verify your registration</h1><p>Enter the 6-digit code sent to <b>{challenge.maskedTarget||"your contact"}</b>.</p><div className="auth-form"><Field label="Verification code" value={code} onChange={v=>setCode(v.replace(/\D/g,"").slice(0,6))}/><small className="auth-note">Verification Code will not exceed 6 digits.</small><ErrorBox text={err}/><Primary disabled={busy||code.length!==6||sec<=0} onClick={()=>void verify()}>{busy?"Verifying…":"Verify Registration"}</Primary><small className="auth-note">{sec<=0?"Verification code has expired.":`Resend available in ${fmt(seconds)}`}</small><button className="text-btn" disabled={seconds>0||busy} onClick={()=>void resend()}>{seconds>0?`Resend (${fmt(seconds)})`:"Resend"}</button></div></Shell>}

function Customizing({go,setUser}:{go:(p:Page)=>void;setUser:(u:User|null)=>void}){const[step,setStep]=useState(0),[err,setErr]=useState(""),labels=["Preparing ReDom","Customizing your experience","Creating your session","Securing your account","Preparing your Home Feed","Finishing up"];useEffect(()=>{const t=setInterval(()=>setStep(v=>Math.min(5,v+1)),6000);let live=true;const started=Date.now();(async()=>{try{const d=JSON.parse(sessionStorage.getItem("redom.registration.verification")||"null")||{};const r=await api<any>("/auth/register/initialize",{method:"POST",body:JSON.stringify({verificationChallengeId:d.verificationChallengeId,reservationId:d.reservationId,flowId:d.flowId,deviceId:deviceId(),language:navigator.language,deviceName:navigator.userAgent,deviceType:"browser",platform:"web",browser:navigator.userAgent,appVersion:"web"})});const remaining=Math.max(0,36000-(Date.now()-started));await new Promise(resolve=>setTimeout(resolve,remaining));if(!live)return;if(!r.success||!r.user||!r.session)throw new Error(r.message||"Unable to finish account setup.");saveSession(r.session);setUser({...r.user});sessionStorage.removeItem(REG_KEY);sessionStorage.removeItem("redom.registration.verification");go("home")}catch(e){if(live)setErr(e instanceof Error?e.message:"Unable to finish account setup.")}})();return()=>{live=false;clearInterval(t)}},[go,setUser]);return <Shell><div className="customizing"><ReDomMark size={64}/><h1>Preparing your ReDom experience</h1><p>Please wait while ReDom prepares your account, session, security and Home Feed.</p><div className="custom-card"><div className="custom-orbit"><ShieldIcon/></div><h2>{labels[step]}</h2><p>Setting up your account securely…</p><div className="progress-track"><i style={{width:((step+1)/6*100)+"%"}}/></div><b>{Math.round((step+1)/6*100)}%</b></div>{err?<div className="alert">{err}<button className="text-btn" onClick={()=>location.reload()}>Try again</button></div>:null}</div></Shell>}
function DeviceVerify({go,setUser}:{go:(p:Page)=>void;setUser:(u:User|null)=>void}){const d=JSON.parse(sessionStorage.getItem("redom.login.challenge")||"null")||{},[code,setCode]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),sec=useTimer(d.expiresAt);const submit=async()=>{setBusy(true);setErr("");try{const r=await api<any>("/auth/verify-login-device",{method:"POST",body:JSON.stringify({challengeId:d.challengeId,code,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",loginSource:"web",appVersion:"web"})});if(r.requiresTwoFactor&&r.twoFactorVerification){sessionStorage.setItem("redom.login.2fa",JSON.stringify(r.twoFactorVerification));go("two-factor");return}if(r.success&&r.user&&r.session){saveSession(r.session);setUser({...r.user});go(routePage()==="support-case"?"support-case":"home")}else setErr(r.message||"Verification failed.")}catch(e){setErr(e instanceof Error?e.message:"Verification failed.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><div className="security-hero"><SvgAsset src={SecurityShieldSvg} className="auth-svg-icon" /></div><h1>Verify this browser</h1><p>Enter the 6-digit code sent to <b>{d.maskedTarget||"your account"}</b>.</p><div className="auth-form"><Field label="Verification code" value={code} onChange={v=>setCode(v.replace(/\D/g,"").slice(0,6))}/><ErrorBox text={err}/><Primary disabled={busy||code.length!==6||sec<=0} onClick={()=>void submit()}>{busy?"Verifying…":"Verify device"}</Primary><small className="auth-note">{sec>0?fmt(sec):"Code expired"}</small><button className="text-btn" onClick={()=>go("login")}>Back to login</button></div></Shell>}

function TwoFactor({go,setUser}:{go:(p:Page)=>void;setUser:(u:User|null)=>void}){const d=JSON.parse(sessionStorage.getItem("redom.login.2fa")||"null")||{},[code,setCode]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),sec=useTimer(d.expiresAt);const submit=async()=>{setBusy(true);setErr("");try{const r=await api<any>("/auth/verify-login-2fa",{method:"POST",body:JSON.stringify({challengeId:d.challengeId,code,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",loginSource:"web",appVersion:"web"})});if(r.success&&r.user&&r.session){saveSession(r.session);setUser({...r.user});go(routePage()==="support-case"?"support-case":"home")}else setErr(r.message||"Invalid verification code.")}catch(e){setErr(e instanceof Error?e.message:"Two-factor verification failed.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><div className="security-hero"><LockIcon/></div><h1>Two-factor authentication</h1><p>Enter the 6-digit code sent to <b>{d.maskedTarget||"your account"}</b>.</p><div className="auth-form"><Field label="6-digit code" value={code} onChange={v=>setCode(v.replace(/\D/g,"").slice(0,6))}/><ErrorBox text={err}/><Primary disabled={busy||code.length!==6||sec<=0} onClick={()=>void submit()}>{busy?"Verifying…":"Verify"}</Primary><small className="auth-note">{sec>0?fmt(sec):"Code expired"}</small><button className="text-btn" onClick={()=>go("login")}>Back to login</button></div></Shell>}

function PolicyPage(){const slug=decodeURIComponent(location.pathname.split("/").pop()||"");const[data,setData]=useState<any>(null),[err,setErr]=useState(""),[busy,setBusy]=useState(true);useEffect(()=>{let live=true;(async()=>{try{const r=await api<any>("/policies/"+encodeURIComponent(slug));if(!r.success)throw new Error(r.message||"Policy not found.");if(live)setData(r)}catch(e){if(live)setErr(e instanceof Error?e.message:"Unable to load this policy.")}finally{if(live)setBusy(false)}})();return()=>{live=false}},[slug]);if(busy)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Loading policy…</h1></Shell>;if(err)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Policy unavailable</h1><ErrorBox text={err}/><button className="text-btn" onClick={()=>location.href="/"}>Go to ReDom</button></Shell>;const d=data?.document||{};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><span className="eyebrow">OFFICIAL REDOM POLICY</span><h1>{d.title||slug}</h1><p>{d.summary||""}</p><small className="auth-note">Version {data?.version||d.version||"current"} · Effective {data?.effectiveAt?new Date(data.effectiveAt).toLocaleDateString():d.effectiveAt?new Date(d.effectiveAt).toLocaleDateString():"current"}</small><div className="auth-form">{(d.sections||[]).map((s:any,i:number)=><section key={i}><h3>{s.heading}</h3><p>{s.body}</p></section>)}</div><button className="text-btn" onClick={()=>location.href="/"}>Back to ReDom</button></Shell>}

function SupportCasePage({go}:{go:(p:Page)=>void}){const caseNumber=(location.pathname.match(/R\d{11}$/i)?.[0]||"").toUpperCase();const[data,setData]=useState<any>(null),[err,setErr]=useState(""),[busy,setBusy]=useState(true);useEffect(()=>{let live=true;(async()=>{try{const r=await api<any>("/support/cases/"+encodeURIComponent(caseNumber));if(!r.success)throw new Error(r.message||"Support case not found.");if(live)setData(r)}catch(e){if(live)setErr(e instanceof Error?e.message:"Unable to load this support case.")}finally{if(live)setBusy(false)}})();return()=>{live=false}},[caseNumber]);if(busy)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Loading your support case…</h1></Shell>;if(err)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Support case unavailable</h1><ErrorBox text={err}/><p>This support link only opens a case owned by the ReDom account that signed in.</p><button className="text-btn" onClick={()=>go("home")}>Back to ReDom</button></Shell>;const messages=data.messages||[];return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><span className="eyebrow">REDOM SUPPORT</span><h1>Case {data.case?.caseNumber||caseNumber}</h1><p>{data.case?.subject||"Your ReDom support case"}</p><small className="auth-note">Status: {data.case?.status||"unknown"}</small><div className="auth-form">{messages.map((m:any)=><div key={m.id} className="side-card"><b>{m.senderType==="ai"?"ReDom Support":m.senderType==="user"?"You":"ReDom"}</b><p>{m.body}</p><small>{m.createdAt?new Date(m.createdAt).toLocaleString():""}</small></div>)}</div><button className="text-btn" onClick={()=>go("home")}>Back to ReDom</button></Shell>}

function Home({user,setUser}:{user:User;setUser:(u:User|null)=>void}){const[posts,setPosts]=useState<any[]>([]),[stories,setStories]=useState<any[]>([]),[suggestions,setSuggestions]=useState<any[]>([]),[busy,setBusy]=useState(true),[err,setErr]=useState("");const load=async()=>{setBusy(true);try{const r=await api<any>("/feed/home?refresh="+Date.now());setPosts(r.posts||[]);setStories(r.friendStories||r.stories||[]);setSuggestions(r.suggestedProfiles||r.friendSuggestions||[]);setErr("")}catch(e){setErr(e instanceof Error?e.message:"Unable to load your Home Feed.")}finally{setBusy(false)}};useEffect(()=>{void load()},[]);const logout=async()=>{try{await api("/auth/logout",{method:"POST"})}catch{}clearSession();setUser(null)};return <div className="home-app"><header className="home-header"><button className="brand" onClick={()=>void load()}><ReDomMark size={35}/><b>ReDom</b></button><span className="home-status">Live ReDom</span><button className="btn secondary" onClick={()=>{window.history.pushState({}, "", "/app/homeFeed"); window.location.reload();}}>Web screens</button><button className="btn secondary" onClick={()=>void logout()}>Log out</button></header><main className="home-main"><section className="feed-column"><div className="welcome-card"><Avatar user={user}/><div><b>Good to see you, {user.firstName}.</b><span>Your ReDom Home Feed</span></div><button className="btn secondary" onClick={()=>void load()}>Refresh</button></div><div className="story-strip"><div className="story-create"><div className="story-avatar"><ReDomMark size={26}/></div><b>Create story</b><small>Story publishing is not exposed until its web flow is implemented.</small></div>{stories.slice(0,8).map((s:any)=><div className="story-item" key={s.id}><Avatar user={s} size={54}/><b>{s.firstName}</b></div>)}</div>{err?<ErrorBox text={err}/>:null}{busy?<div className="skeleton"><i/><i/><i/></div>:posts.length?posts.map((p:any)=><Post key={p.id} p={p}/>):<div className="empty"><HomeIcon/><h3>Your Home Feed is ready</h3><p>Posts from people, pages and recommendations will appear here.</p></div>}</section><aside className="home-side"><div className="side-card"><h3>People you may know</h3>{suggestions.slice(0,5).map((s:any)=><div className="person-row" key={s.userId}><Avatar user={s} size={40}/><div><b>{s.firstName} {s.lastName}</b><small>@{s.username}</small></div></div>)}</div><div className="side-card"><h3>Web development status</h3><p>The web app stops at the currently implemented Home Feed boundary. No unfinished navigation buttons are exposed.</p></div></aside></main></div>}
function Avatar({user,size=44}:{user:any;size?:number}){return user?.profilePhoto?<img className="avatar-img" src={user.profilePhoto} alt="" style={{width:size,height:size}}/>:<span className="avatar-fallback" style={{width:size,height:size}}>{String(user?.firstName||"R")[0].toUpperCase()}</span>}
function Post({p}:{p:any}){const[liked,setLiked]=useState(!!p.reactionSummary?.myReaction),[count,setCount]=useState(Number(p.reactionSummary?.total||0));const react=async()=>{try{const r=await api<any>("/feed/post-reaction",{method:"POST",body:JSON.stringify({postId:p.id,reactionType:liked?"":"like"})});setLiked(!liked);setCount(Number(r.total??r.reactionTotal??count+(liked?-1:1)))}catch{}};return <article className="web-post"><div className="post-head"><Avatar user={p} size={45}/><div><b>{p.firstName} {p.lastName}</b><small>@{p.username}</small></div></div>{p.content?<p className="post-content">{p.content}</p>:null}{p.media?.[0]?.objectKey?<img className="post-image" src={p.media[0].objectKey} alt=""/>:<div className="post-art"><ReDomMark size={72}/></div>}<div className="post-meta"><span>{count} reactions</span></div><button className={liked?"post-like liked":"post-like"} onClick={()=>void react()}>♡ {liked?"Liked":"Like"}</button></article>}
export default function App(){const[page,setPage]=useState<Page>(()=>{const routed=routePage();return routed==="policy"||routed==="support-case"?routed:"startup"}),[network,setNetwork]=useState<NetworkProviderResponse|null>(null),[user,setUser]=useState<User|null>(null),[ready,setReady]=useState(false);const go=(p:Page)=>{const path=pagePath(p);if(path)window.history.pushState({}, "", path);setPage(p);window.scrollTo({top:0,behavior:"smooth"});};useEffect(()=>{const s=getSession();if(s){api<any>("/profile").then(r=>{if(r.profile)setUser({...r.profile,id:r.profile.userId})}).catch(()=>clearSession()).finally(()=>setReady(true))}else setReady(true)},[]);if(!ready)return <div className="boot"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b><span>Loading…</span></div>;if(page==="startup")return <Startup done={()=>go(user?"home":"login")} setNetwork={setNetwork}/>;if(page==="policy")return <PolicyPage/>;if(page==="support-case")return user?<SupportCasePage go={go}/>:<Login go={go} network={network} setUser={setUser}/>;if(page==="web-parity")return user?<WebExperience user={user} onLogout={async()=>{try{await api("/auth/logout",{method:"POST"})}catch{}clearSession();setUser(null);window.history.pushState({}, "", "/");go("startup");}}/>:<Login go={go} network={network} setUser={setUser}/>;if(page==="login")return <Login go={go} network={network} setUser={setUser}/>;if(page==="find-account")return <FindAccount go={go}/>;if(page==="reset-code")return <ResetCode go={go}/>;if(page==="reset-password")return <ResetPassword go={go}/>;if(page==="device-verify")return <DeviceVerify go={go} setUser={setUser}/>;if(page==="two-factor")return <TwoFactor go={go} setUser={setUser}/>;const f=readReg();if(page==="register-welcome")return <RegisterWelcome go={go}/>;if(!f&&page!=="home")return <Login go={go} network={network} setUser={setUser}/>;if(page==="register-identity")return <RegIdentity flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-birthday")return <RegBirthday flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-gender")return <RegGender flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-phone")return <RegPhone flow={f!} go={go} setFlow={writeReg} network={network}/>;if(page==="register-email")return <RegEmail flow={f!} go={go} setFlow={writeReg} network={network}/>;if(page==="register-password")return <RegPassword flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-review")return <RegReview flow={f!} go={go} network={network}/>;if(page==="register-verify")return <RegVerify go={go}/>;if(page==="customizing")return <Customizing go={go} setUser={setUser}/>;return user?<Home user={user} setUser={setUser}/>:<Login go={go} network={network} setUser={setUser}/>}
